SELECT CASE WHEN duration_sec >= 412 THEN 'high' WHEN duration_sec >= 104 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SUM(duration_sec) AS total_duration_sec, COUNT(*) AS cnt, ROUND(SUM(duration_sec) * 100.0 / SUM(SUM(duration_sec)) OVER (), 2) AS pct_of_total FROM web_events GROUP BY CASE WHEN duration_sec >= 412 THEN 'high' WHEN duration_sec >= 104 THEN 'mid' ELSE 'low' END ORDER BY cnt DESC, duration_sec_bucket LIMIT 5;
